  this.buildGrid();s.cast-=dt;let target=this.nearest(p,s.char.range*s.rangeMul);if(s.cast<=0&&target){this.attack(target);if(s.mode==='finished')return;s.cast=s.char.cooldown*s.cdMul}for(const prop of s.props)if(prop.type==='barrel'&&!prop.open&&this.dist(p,prop)<100&&s.cast<=0){prop.hp-=s.char.attack;s.cast=.5;this.ring(prop.x,prop.y,25,'#dbb16a',.2);if(prop.hp<=0){prop.open=true;s.drops.push({x:prop.x,y:prop.y,type:this.rand()<.5?'food':'gold',value:20})}break}
